import React from 'react';
import TableBasic from '@/components/registry/samples/TableBasic.jsx';

export default function Example() {
  const columns = [
    { key: 'name', header: 'Name' },
    { key: 'role', header: 'Role' },
    { key: 'email', header: 'Email' }
  ];
  const data = [
    { name: 'Alice Johnson', role: 'Designer', email: 'alice@example.com' },
    { name: 'Ben Wright', role: 'Engineer', email: 'ben@example.com' },
    { name: 'Cara Lee', role: 'PM', email: 'cara@example.com' }
  ];
  return <TableBasic columns={columns} data={data} caption="Team directory" />;
}

import React from 'react';
import TableSortable from '@/components/registry/samples/TableSortable.jsx';

export default function Example() {
  const columns = [
    { key: 'name', header: 'Name', sortable: true },
    { key: 'role', header: 'Role', sortable: true },
    { key: 'email', header: 'Email' }
  ];
  const data = [
    { name: 'Alice Johnson', role: 'Designer', email: 'alice@example.com' },
    { name: 'Ben Wright', role: 'Engineer', email: 'ben@example.com' },
    { name: 'Cara Lee', role: 'PM', email: 'cara@example.com' }
  ];
  return (
    <TableSortable
      columns={columns}
      data={data}
      initialSort={{ key: 'name', direction: 'asc' }}
      caption="Team directory sortable"
    />
  );
}
